      "守卫金麦农场的新住民，擅长以高生命熊族随从稳固战线。": "황금밀 농장을 지키는 새 주민. 체력이 높은 곰족 하수인으로 전선을 굳히는 데 능숙합니다.",
      "农垦本能": "개간 본능",
      "每2个敌方行动回合召唤1个会随进度成长的巡田熊民。": "적의 행동 턴 2회마다 진행도에 따라 성장하는 순찰 곰족 하나를 소환합니다.",
      "女王之血唤醒的史莱姆，以厚重生命、分裂与持续再生缓慢推进战线。": "여왕의 피로 깨어난 슬라임. 두터운 체력과 분열, 지속적인 재생으로 천천히 전선을 밀어붙입니다.",
      "胶质再生": "젤 재생",
      "每个敌方行动回合，为首领和全部史莱姆随从恢复生命。": "적의 행동 턴마다 보스와 모든 슬라임 하수인의 체력을 회복합니다.",
      "喝下女王之血后开智的灰狼与野兽，攻击迅猛但防御薄弱，许多单位登场便会扑击。": "여왕의 피를 마시고 지혜를 얻은 회색 늑대와 짐승들. 공격은 날카롭지만 방어는 약하며, 다수가 등장하자마자 덤벼듭니다.",
