      "法力不足。": "마나가 부족합니다.",
      "战场已经没有空位。": "전장에 빈자리가 없습니다.",
      "敌方前排没有目标。": "적 전열에 대상이 없습니다.",
      "敌方战场上没有目标。": "적 전장에 대상이 없습니다.",
      "没有可以撤回的友方随从。": "손으로 되돌릴 아군 하수인이 없습니다.",
