      "我方战场已经没有空位。": "아군 전장에 빈자리가 없습니다.",
      "敌方战场上没有随从。": "적 전장에 하수인이 없습니다.",
      "英雄生命值已经全满。": "영웅의 체력이 이미 가득 찼습니다.",
      "生命值过低，无法发动这个技能。": "체력이 너무 낮아 이 기술을 쓸 수 없습니다.",
      "治疗随从本回合已经使用过治疗。": "이 치유 하수인은 이번 턴에 이미 치유했습니다.",
      "这个随从本回合不能攻击。": "이 하수인은 이번 턴에 공격할 수 없습니다.",
      "你把火焰瓶砸向盾阵中央，烈焰没有伤到罗德里克，却令八面盾牌同时失去秩序。斩首窗口已经出现。": "화염병을 방패진 한가운데에 던졌다. 불길은 로데릭에게 닿지 않았지만, 여덟 개의 방패가 동시에 흐트러졌다. 목을 벨 틈이 생겼다.",
      "前排": "전열",
