      "进军王庭": "왕궁으로 진군",
      "挑战翠影女王": "비취 그림자 여왕에게 도전하라",
      "击穿战线": "전선을 돌파하라",
      "直面狼王": "늑대왕과 맞서라",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "제5장은 비취성 남쪽의 옛 도시 폐허입니다. 회색 늑대와 다른 짐승들이 속도와 기습으로 영역을 넓히고 있으며, 마지막으로 은회색 늑대 여사냥꾼과 맞섭니다.",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "제4장에는 슬라임 보스 노드가 20개 있습니다. 체력이 두텁고 공격력은 낮으며 끊임없이 재생합니다. 빛나는 시냇물을 따라 숲 깊숙이 들어가 마지막으로 벽로의 대현자 네프리와 맞섭니다.",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "제3장에는 곰족 보스 노드 20개와 농가 한 채가 있습니다. 농로를 따라 점령된 마을을 조사하고, 마지막으로 풍요이삭 전쟁어미 브레아와 맞섭니다.",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "제2장에는 보스 노드가 20개 있습니다. 고블린 군단의 방어선을 따라 전진해, 마지막으로 체력 200의 비취 그림자 여왕과 맞섭니다.",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "전열과 후열로 이루어진 네 개의 전선에 군대를 배치하고, 한 줄기 돌파구를 열어 안개 숲의 노드 13개를 지나가세요. 모든 승리가 다음 원정의 힘이 됩니다.",
