      "你施放{0}（{1}费），为{2}恢复{3}点生命。": "당신은 {0}을(를) 시전해(비용 {1}) {2}의 체력을 {3} 회복했습니다.",
      "你施放{0}（{1}费），{2}获得+{3}最大生命与再生。": "당신은 {0}을(를) 시전했습니다(비용 {1}). {2}이(가) 최대 체력 +{3}과(와) 재생을 얻었습니다.",
      "你施放{0}（{1}费），召唤{2}个{3}/{4}软泥分身。": "당신은 {0}을(를) 시전해(비용 {1}) {3}/{4} 진흙 분신 {2}명을 소환했습니다.",
      "你施放{0}（{1}费），英雄恢复{2}点生命，友方全体恢复{3}点生命{4}。": "당신은 {0}을(를) 시전해(비용 {1}) 영웅의 체력을 {2}, 아군 전체의 체력을 {3} 회복했습니다{4}.",
