      "{0}触发：消灭随从，抽1张牌。": "{0} 발동: 하수인을 처치해 카드를 1장 뽑습니다.",
      "{0}饮下战意，攻击力提升至{1}。": "{0}이(가) 투지를 들이켜 공격력이 {1}(으)로 올랐습니다.",
