      "{0}对第{1}路{2}的{3}造成{4}点伤害{5}；目标剩余{6}/{7}生命。": "{0}이(가) 제{1}라인 {2}의 {3}에게 피해를 {4} 주었습니다{5}. 대상의 남은 체력 {6}/{7}.",
