      "你结束第{0}回合，保留{1}张手牌；{2}开始行动。": "당신은 제{0}턴을 마치고 손패 {1}장을 남겼습니다. {2}이(가) 행동을 시작합니다.",
      "{0}第{1}个行动回合开始：法力恢复为{2}/{3}，场上有{4}个随从。": "{0}의 제{1}행동 턴 시작: 마나가 {2}/{3}(으)로 회복, 전장의 하수인 {4}명.",
