      "{0}施放{1}，剩余{2}/{3}法力。": "{0}이(가) {1}을(를) 시전했습니다. 남은 마나 {2}/{3}.",
      "{0}从第{1}路{2}发起攻击，通过第{3}路突破口命中我方英雄，造成{4}点伤害；我方英雄剩余{5}/{6}生命。": "{0}이(가) 제{1}라인 {2}에서 공격해 제{3}라인 돌파구를 통해 아군 영웅에게 피해를 {4} 주었습니다. 아군 영웅의 남은 체력 {5}/{6}.",
