      "{0}发动「{1}」，但敌方战场已经占满。": "{0}이(가) '{1}'을(를) 발동했지만 적 전장이 이미 가득 찼습니다.",
      "{0}发动「{1}」：在第{2}路{3}召唤突击灰狼（4攻/1血），它可以立即攻击随从。": "{0}이(가) '{1}' 발동: 제{2}라인 {3}에 돌격 회색 늑대(4/1)를 소환했습니다. 즉시 하수인을 공격할 수 있습니다.",
      "{0}试图召唤普通哥布林，但敌方战场已经占满。": "{0}이(가) 일반 고블린을 소환하려 했지만 적 전장이 이미 가득 찼습니다.",
